var o=169;var a=`169-roux-and-flour-based-thickening`;var i=`161`;var r={en:`Roux and Flour-Based Thickening`,ua:`Ру та загущення борошном`};var n={short:`Roux is a cooked mixture of flour and fat used to thicken sauces and soups. Its cooking degree (from white through blond to brown) changes color, flavor, and thickening power.`,sections:[{title:`Core idea`,text:`In a typical roux, fat coats and disperses flour so it can be incorporated with fewer lumps. Pale roux tastes neutral and thickens efficiently; longer-cooked roux develops nutty color and flavor but usually thickens less per gram.`},{title:`Scientific / practical principles`,text:`Flour starch granules absorb water, swell, and thicken the surrounding liquid on heating. Fat helps separate particles before the starch contacts water. Continued cooking helps remove a raw-flour impression; excessive heat can scorch the starch and fat.`},{title:`How to apply it`,text:`Cook roughly equal masses of flour and fat for a reproducible starting roux. Whisk in compatible liquid gradually, simmer until starch is hydrated and the flour taste subsides, and adjust consistency with more liquid. Follow a tested formula when exact viscosity matters.`},{title:`Practical example`,text:`Make three mini-batches using 15 g flour and 15 g butter each; cook to white, blond, and brown, then add equal amounts of warm milk. Compare color, aroma, thickness, and whether the darkest roux needs more thickener.`},{title:`Common mistakes and limitations`,text:`Equal weights of flour and fat are a learning baseline, not a required ratio in every recipe. Adding cold liquid or warm liquid can both work with good technique; rough stirring, too little dispersion, or rapid boiling may form lumps.`},{title:`Related theories`,text:`053, 168, 170, 177.`}]};var s={short:`Ру є прогрітою сумішшю борошна та жиру, якою загущують супи й соуси. Ступінь обсмаження (від світлого до золотистого й коричневого) змінює колір, смак і силу загущення.`,sections:[{title:`Суть`,text:`Жир розподіляє частинки борошна, полегшуючи введення в рідину без грудок. Світлий ру має нейтральніший смак і добре загущує; темний набуває горіхового відтінку, але зазвичай гірше загущує за однакової маси.`},{title:`Наукові та практичні принципи`,text:`Під час нагрівання крохмальні зерна вбирають воду, набухають і підвищують в’язкість. Жир допомагає відокремити частинки борошна до контакту з водою. Подальше прогрівання прибирає сирий борошнистий присмак; перегрів здатний спалити суміш.`},{title:`Як застосовувати`,text:`Для навчання візьміть приблизно однакові маси борошна й жиру. Поступово введіть відповідну рідину вінчиком, проваріть до повного загущення, відкоригуйте густину. Для точного результату орієнтуйтеся на перевірену рецептуру.`},{title:`Практичний приклад`,text:`Зробіть три маленькі ру з 15 г борошна й 15 г масла кожне. Доведіть їх до світлого, золотистого й темного кольору, додайте однакові об’єми теплого молока. Порівняйте аромат, колір і густину.`},{title:`Поширені помилки й обмеження`,text:`Однакові маси жиру й борошна є зручним початком, а не обов’язковою вимогою. Працювати можна з різними температурами рідини за правильної техніки; поспішне змішування та погана дисперсія призводять до грудок.`},{title:`Пов’язані теорії`,text:`053, 168, 170, 177.`}]};var l=[53,168,170,177];var c=`References / Джерела`;var d=[`https://www.ciachef.edu/wp-content/uploads/2024/07/examining-sauces.pdf`,`https://www.kingarthurbaking.com/blog/2022/03/07/leftover-oatmeal-soft-chewy-porridge-bread`];var u={id:169,slug:a,group:`161`,title:r,en:n,ua:s,related:l,referenceTitle:c,references:d};export{u as default,n as en,i as group,o as id,c as referenceTitle,d as references,l as related,a as slug,r as title,s as ua};